//! Trie node representation for the persistent vector.
//!
//! `immer::vector` (like Clojure's `PersistentVector` and the RRB-tree family it
//! is derived from) stores its elements in a *bit-partitioned vector trie*: a
//! tree of fixed-width nodes where the radix-`B` digits of an element's index
//! spell out the path from the root down to the leaf holding it.
//!
//! With a branching factor of `B = 32` each level consumes `BITS = 5` bits of
//! the index, so lookup is `O(log32 n)` — effectively constant for any vector
//! that fits in memory — and `push_back` only has to copy the `O(log32 n)` nodes
//! along one root-to-leaf path. Every untouched node is shared with the previous
//! version through reference counting, which is what makes the structure
//! *persistent*: the old vector stays alive, valid, and unchanged.

use std::rc::Rc;

/// Number of index bits consumed per trie level.
pub const BITS: u32 = 5;

/// Branching factor of the trie: `2^BITS` children per inner node.
pub const BRANCHING: usize = 1 << BITS;

/// Mask selecting the index bits belonging to a single level.
pub const MASK: usize = BRANCHING - 1;

/// A node of the vector trie.
///
/// Nodes are always reached through an [`Rc`], which is what implements the
/// structural sharing between vector versions. A node is immutable once built;
/// "modifying" a vector means building fresh nodes along one path and sharing
/// every sibling subtree with the source vector.
///
/// Invariants (upheld by [`super::vector::Vector`]):
///
/// * A node at level `l > 0` is always [`Node::Inner`]; a node at level `0` is
///   always [`Node::Leaf`].
/// * Children are packed left-to-right with no gaps, so an inner node's
///   `children.len()` is exactly its number of populated slots.
/// * `children.len() <= BRANCHING` and `elems.len() <= BRANCHING`.
/// * Every leaf that lives *inside the trie* is completely full
///   (`elems.len() == BRANCHING`); a partially filled trailing leaf is held
///   outside the trie, in the vector's tail.
pub enum Node<T> {
    /// Interior node: `BRANCHING`-way fan-out to child nodes one level down.
    Inner(Vec<Rc<Node<T>>>),
    /// Leaf node: a chunk of up to `BRANCHING` consecutive elements.
    Leaf(Vec<T>),
}

impl<T> Node<T> {
    /// A fresh inner node with no children.
    pub fn empty_inner() -> Rc<Node<T>> {
        Rc::new(Node::Inner(Vec::new()))
    }

    /// The children of an inner node.
    ///
    /// # Panics
    ///
    /// Panics if called on a leaf, which would mean the level bookkeeping in
    /// [`super::vector::Vector`] had gone wrong.
    pub fn children(&self) -> &Vec<Rc<Node<T>>> {
        match self {
            Node::Inner(children) => children,
            Node::Leaf(_) => unreachable!("expected an inner node, found a leaf"),
        }
    }

    /// The elements of a leaf node.
    ///
    /// # Panics
    ///
    /// Panics if called on an inner node.
    pub fn elems(&self) -> &[T] {
        match self {
            Node::Leaf(elems) => elems,
            Node::Inner(_) => unreachable!("expected a leaf, found an inner node"),
        }
    }

    /// Whether this node is a leaf.
    pub fn is_leaf(&self) -> bool {
        matches!(self, Node::Leaf(_))
    }
}

/// Builds the single-child chain that hangs a finished leaf at depth `level`.
///
/// When a new leaf has to be attached somewhere the trie has no branch yet, the
/// intervening inner nodes must be created: `new_path` returns a spine of
/// one-child nodes from `level` down to the leaf. `level == 0` means "the leaf
/// belongs right here", so the node is returned as-is.
pub fn new_path<T>(level: u32, node: Rc<Node<T>>) -> Rc<Node<T>> {
    debug_assert!(node.is_leaf(), "new_path always terminates in a leaf");
    if level == 0 {
        node
    } else {
        Rc::new(Node::Inner(vec![new_path(level - BITS, node)]))
    }
}

