//! Forward iteration over a persistent vector.
//!
//! The naive way to iterate a vector trie is to call the indexing routine once
//! per element, which re-descends the trie every time: `O(n log n)` overall.
//! [`Iter`] instead keeps the current root-to-leaf path on an explicit stack and
//! walks it like an odometer, so each `next()` is amortised `O(1)` and a full
//! traversal is `O(n)` — the same shape as the chunked iterators the C++
//! original uses.

use std::rc::Rc;

use super::node::Node;
use super::vector::Vector;

/// Borrowing forward iterator over the elements of a [`Vector`].
///
/// Created by [`Vector::iter`], or by `for x in &vector`.
pub struct Iter<'a, T> {
    /// The inner nodes on the path to `leaf`, each paired with the index of the
    /// child *after* the one we descended into.
    stack: Vec<(&'a [Rc<Node<T>>], usize)>,
    /// The chunk currently being handed out (a trie leaf, or the tail).
    leaf: &'a [T],
    /// How far into `leaf` we are.
    pos: usize,
    /// Elements still inside the trie proper (excludes the tail).
    tree_left: usize,
    /// The vector's trailing chunk, visited once the trie is exhausted.
    tail: &'a [T],
    /// Whether `leaf` is already the tail.
    in_tail: bool,
    /// Total elements not yet yielded; drives `size_hint`.
    left: usize,
}

impl<'a, T> Iter<'a, T> {
    pub(super) fn new(vector: &'a Vector<T>) -> Iter<'a, T> {
        let tree_left = vector.tail_offset();
        let tail = vector.tail_slice();
        let mut iter = Iter {
            stack: Vec::new(),
            leaf: &[],
            pos: 0,
            tree_left,
            tail,
            in_tail: false,
            left: vector.size(),
        };
        if tree_left > 0 {
            // Descend the leftmost path of the trie to prime `leaf`.
            iter.descend_leftmost(vector.root(), vector.shift());
        } else {
            iter.enter_tail();
        }
        iter
    }

    /// Walks from `node` at `level` down to its leftmost leaf, recording the
    /// path so `advance` can resume from it.
    fn descend_leftmost(&mut self, node: &'a Rc<Node<T>>, level: u32) {
        let mut node: &'a Node<T> = node;
        let mut level = level;
        while level > 0 {
            let children = node.children();
            debug_assert!(!children.is_empty(), "populated subtrees are never empty");
            self.stack.push((children, 1));
            node = &children[0];
            level -= super::node::BITS;
        }
        self.leaf = node.elems();
        self.pos = 0;
    }

    /// Switches the iterator over to the tail chunk.
    fn enter_tail(&mut self) {
        self.in_tail = true;
        self.leaf = self.tail;
        self.pos = 0;
    }

    /// Moves to the next chunk once the current one is used up.
    fn advance_chunk(&mut self) {
        if self.in_tail {
            // Nothing follows the tail; `left == 0` stops the iteration.
            self.leaf = &[];
            self.pos = 0;
            return;
        }
        if self.tree_left == 0 {
            self.enter_tail();
            return;
        }
        // Odometer step: unwind to the deepest level with an unvisited child,
        // then descend that subtree's leftmost path.
        while let Some((children, next)) = self.stack.pop() {
            if next < children.len() {
                self.stack.push((children, next + 1));
                let level = (self.stack.len() as u32) * super::node::BITS;
                // `level` counts the inner levels still below this child.
                let child = &children[next];
                self.descend_from(child, level);
                return;
            }
        }
        self.enter_tail();
    }

    /// Descends `child`, which sits below `inner_levels_above` recorded levels.
    fn descend_from(&mut self, child: &'a Rc<Node<T>>, _inner_levels_above: u32) {
        let mut node: &'a Node<T> = child;
        // Keep descending while the node is an inner node; the trie's uniform
        // depth guarantees this lands on a leaf.
        while !node.is_leaf() {
            let children = node.children();
            debug_assert!(!children.is_empty(), "populated subtrees are never empty");
            self.stack.push((children, 1));
            node = &children[0];
        }
        self.leaf = node.elems();
        self.pos = 0;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.left == 0 {
            return None;
        }
        while self.pos >= self.leaf.len() {
            self.advance_chunk();
            if self.leaf.is_empty() {
                // Defensive: `left > 0` should always find another chunk.
                return None;
            }
        }
        let item = &self.leaf[self.pos];
        self.pos += 1;
        self.left -= 1;
        if !self.in_tail {
            self.tree_left -= 1;
        }
        Some(item)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.left, Some(self.left))
    }
}

impl<'a, T> ExactSizeIterator for Iter<'a, T> {
    fn len(&self) -> usize {
        self.left
    }
}

impl<'a, T> std::iter::FusedIterator for Iter<'a, T> {}

/// Consuming iterator, yielding clones of the elements in order.
///
/// A persistent vector's storage may be shared with other versions, so the
/// elements cannot be moved out; cloning is the faithful behaviour.
pub struct IntoIter<T> {
    vector: Vector<T>,
    index: usize,
}

impl<T> IntoIter<T> {
    pub(super) fn new(vector: Vector<T>) -> IntoIter<T> {
        IntoIter { vector, index: 0 }
    }
}

impl<T: Clone> Iterator for IntoIter<T> {
    type Item = T;

    fn next(&mut self) -> Option<T> {
        let item = self.vector.get(self.index)?.clone();
        self.index += 1;
        Some(item)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let left = self.vector.size() - self.index;
        (left, Some(left))
    }
}

impl<T: Clone> ExactSizeIterator for IntoIter<T> {}

