//! An immutable (persistent) vector with structural sharing.
//!
//! This is a from-scratch re-implementation of the contract offered by
//! `immer::vector<T>`: default construction, `size()`, `operator[]`,
//! `push_back()` returning a *new* vector, and forward iteration.
//!
//! # Representation
//!
//! ```text
//!                        root (shift = 10)
//!                       /            \
//!            inner (shift = 5)      inner (shift = 5)      tail
//!            /      |     \              |                [ .. ]  <= up to 32
//!        leaf     leaf    leaf         leaf                        pending elems
//!      [0..32) [32..64) [64..96)    [1024..1056)
//! ```
//!
//! * The **trie** holds a whole number of full 32-element leaves. An index is
//!   routed by its radix-32 digits: digit `(i >> shift) & 31` picks the root's
//!   child, the next digit the grandchild, and so on until `shift` reaches 0.
//! * The **tail** is the trailing, still-growing chunk. Keeping it outside the
//!   trie is what makes `push_back` `O(1)` for 31 out of every 32 calls: only
//!   the small tail chunk is copied, and the trie is untouched.
//!
//! Every node is behind an [`Rc`], so a `push_back` shares all of the source
//! vector's nodes except the `O(log32 n)` on the path it had to rebuild. The
//! source vector remains fully valid — that is the persistence guarantee the C++
//! original relies on when it writes `v = v.push_back(x)` in a loop while older
//! versions may still be referenced elsewhere.
//!
//! # Complexity
//!
//! | operation      | cost                          |
//! |----------------|-------------------------------|
//! | `push_back`    | `O(1)` amortised (`O(log32 n)` worst case) |
//! | `operator[]`   | `O(log32 n)`                  |
//! | `update`       | `O(log32 n)`                  |
//! | `clone`        | `O(1)` (reference-count bumps)|
//! | full iteration | `O(n)`                        |

use std::fmt;
use std::ops::Index;
use std::rc::Rc;

use super::iter::{IntoIter, Iter};
use super::node::{new_path, Node, BITS, BRANCHING, MASK};

/// An immutable vector of `T` with `O(1)` copies and structural sharing.
///
/// Mirrors `immer::vector<T>`: mutating operations consume `&self` and return a
/// brand-new value, leaving the receiver untouched.
pub struct Vector<T> {
    /// Total number of elements, trie plus tail.
    size: usize,
    /// Index bits consumed at the root. Leaves sit at level 0, so the trie's
    /// depth is `shift / BITS + 1`.
    shift: u32,
    /// Root of the trie; always an inner node, empty when the trie is empty.
    root: Rc<Node<T>>,
    /// Trailing chunk of up to `BRANCHING` elements.
    tail: Rc<Vec<T>>,
}

impl<T> Vector<T> {
    /// Creates an empty vector. Equivalent to `immer::vector<T>{}`.
    pub fn new() -> Vector<T> {
        Vector {
            size: 0,
            shift: BITS,
            root: Node::empty_inner(),
            tail: Rc::new(Vec::new()),
        }
    }

    /// Number of elements, matching `immer::vector::size()`.
    pub fn size(&self) -> usize {
        self.size
    }

    /// Number of elements. Rust-idiomatic alias for [`Vector::size`].
    pub fn len(&self) -> usize {
        self.size
    }

    /// Whether the vector has no elements.
    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    /// Index of the first element held in the tail rather than in the trie.
    ///
    /// Equal to `size` rounded *down* to a multiple of `BRANCHING`, except that a
    /// vector of exactly `BRANCHING` elements still keeps them all in the tail
    /// (the trie only gains a leaf once a 33rd element arrives). Expressing it as
    /// `((size - 1) >> BITS) << BITS` gets both cases with one formula.
    pub(super) fn tail_offset(&self) -> usize {
        if self.size < BRANCHING {
            0
        } else {
            ((self.size - 1) >> BITS) << BITS
        }
    }

    /// The trailing chunk.
    pub(super) fn tail_slice(&self) -> &[T] {
        &self.tail
    }

    /// The trie root.
    pub(super) fn root(&self) -> &Rc<Node<T>> {
        &self.root
    }

    /// Index bits consumed at the root.
    pub(super) fn shift(&self) -> u32 {
        self.shift
    }

    /// Returns the 32-element chunk containing index `i`.
    ///
    /// `i` must be `< size`. Routing is pure radix arithmetic: peel `BITS` bits
    /// off the index at every level, most significant digit first.
    fn leaf_for(&self, i: usize) -> &[T] {
        debug_assert!(i < self.size);
        if i >= self.tail_offset() {
            return &self.tail;
        }
        let mut node: &Node<T> = &self.root;
        let mut level = self.shift;
        while level > 0 {
            node = &node.children()[(i >> level) & MASK];
            level -= BITS;
        }
        node.elems()
    }

    /// Returns a reference to the element at `i`, or `None` if out of bounds.
    ///
    /// The checked counterpart to [`Index`]; `immer::vector` has no equivalent,
    /// since C++'s `operator[]` on an out-of-range index is undefined behaviour.
    pub fn get(&self, i: usize) -> Option<&T> {
        if i >= self.size {
            None
        } else {
            Some(&self.leaf_for(i)[i & MASK])
        }
    }

    /// First element, or `None` when empty.
    pub fn front(&self) -> Option<&T> {
        self.get(0)
    }

    /// Last element, or `None` when empty.
    pub fn back(&self) -> Option<&T> {
        if self.size == 0 {
            None
        } else {
            self.get(self.size - 1)
        }
    }

    /// Borrowing forward iterator, in index order.
    pub fn iter(&self) -> Iter<'_, T> {
        Iter::new(self)
    }
}

impl<T: Clone> Vector<T> {
    /// Returns a new vector with `value` appended; `self` is unchanged.
    ///
    /// Three cases, in order of frequency:
    ///
    /// 1. **Tail has room** (31 of every 32 calls) — copy the tail chunk, push
    ///    onto the copy, share the whole trie.
    /// 2. **Tail is full, trie has room** — freeze the tail into a leaf and
    ///    graft it into the trie, copying only the nodes along its path; the new
    ///    value starts a fresh one-element tail.
    /// 3. **Tail is full and the trie is full** — grow the trie one level: a new
    ///    root whose first child is the old root and whose second child is a
    ///    fresh spine down to the frozen tail.
    pub fn push_back(&self, value: T) -> Vector<T> {
        if self.tail.len() < BRANCHING {
            // Case 1: room in the tail.
            let mut tail = (*self.tail).clone();
            tail.push(value);
            return Vector {
                size: self.size + 1,
                shift: self.shift,
                root: Rc::clone(&self.root),
                tail: Rc::new(tail),
            };
        }

        let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
        let (root, shift) = if self.is_root_full() {
            // Case 3: deepen the trie.
            let root = Rc::new(Node::Inner(vec![
                Rc::clone(&self.root),
                new_path(self.shift, leaf),
            ]));
            (root, self.shift + BITS)
        } else {
            // Case 2: graft the frozen tail into the existing trie.
            (push_leaf(self.size, self.shift, &self.root, leaf), self.shift)
        };

        Vector {
            size: self.size + 1,
            shift,
            root,
            tail: Rc::new(vec![value]),
        }
    }

    /// Whether the trie cannot accept another leaf at the current depth.
    ///
    /// A root at `shift` addresses `1 << shift` leaf slots — i.e. `BRANCHING <<
    /// shift` elements. `size >> BITS` is the number of leaves the trie would
    /// hold after the full tail is grafted in, minus nothing: when that count
    /// exceeds the addressable slots, the root must grow. Only called with a
    /// full tail, so `size` is a positive multiple of `BRANCHING`.
    fn is_root_full(&self) -> bool {
        (self.size >> BITS) > (1usize << self.shift)
    }

    /// Returns a new vector with index `i` replaced by `value`.
    ///
    /// Copies only the `O(log32 n)` nodes on the path to `i`; `self` is
    /// unchanged. Returns `None` if `i` is out of bounds.
    pub fn update(&self, i: usize, value: T) -> Option<Vector<T>> {
        if i >= self.size {
            return None;
        }
        if i >= self.tail_offset() {
            let mut tail = (*self.tail).clone();
            tail[i & MASK] = value;
            return Some(Vector {
                size: self.size,
                shift: self.shift,
                root: Rc::clone(&self.root),
                tail: Rc::new(tail),
            });
        }
        Some(Vector {
            size: self.size,
            shift: self.shift,
            root: update_path(i, self.shift, &self.root, value),
            tail: Rc::clone(&self.tail),
        })
    }
}

/// Grafts a full `leaf` into the trie rooted at `parent`.
///
/// `size` is the element count *before* the push, so `size - 1` is the index of
/// the last element of the leaf being inserted, and its radix digits spell out
/// where the leaf belongs. At each level the digit either selects an existing
/// child to recurse into or points one past the last child, meaning a fresh
/// spine has to be created there.
fn push_leaf<T>(
    size: usize,
    level: u32,
    parent: &Rc<Node<T>>,
    leaf: Rc<Node<T>>,
) -> Rc<Node<T>> {
    let subidx = ((size - 1) >> level) & MASK;
    let children = parent.children();
    debug_assert!(
        subidx <= children.len() && children.len() < BRANCHING,
        "the trie fills left-to-right with no gaps"
    );

    let insert = if level == BITS {
        // One level above the leaves: this is where the leaf lands.
        leaf
    } else if subidx < children.len() {
        push_leaf(size, level - BITS, &children[subidx], leaf)
    } else {
        new_path(level - BITS, leaf)
    };

    // Copy this node (cheap: a vector of at most 32 reference-count bumps) and
    // splice in the rebuilt child. Every sibling subtree stays shared.
    let mut copy = children.clone();
    if subidx < copy.len() {
        copy[subidx] = insert;
    } else {
        copy.push(insert);
    }
    Rc::new(Node::Inner(copy))
}

/// Rebuilds the path to index `i`, replacing that element with `value`.
fn update_path<T: Clone>(i: usize, level: u32, node: &Rc<Node<T>>, value: T) -> Rc<Node<T>> {
    if level == 0 {
        let mut elems = node.elems().to_vec();
        elems[i & MASK] = value;
        return Rc::new(Node::Leaf(elems));
    }
    let children = node.children();
    let subidx = (i >> level) & MASK;
    let mut copy = children.clone();
    copy[subidx] = update_path(i, level - BITS, &children[subidx], value);
    Rc::new(Node::Inner(copy))
}

impl<T> Clone for Vector<T> {
    /// `O(1)`: copies the two handles and bumps their reference counts, exactly
    /// like copying an `immer::vector`.
    fn clone(&self) -> Vector<T> {
        Vector {
            size: self.size,
            shift: self.shift,
            root: Rc::clone(&self.root),
            tail: Rc::clone(&self.tail),
        }
    }
}

impl<T> Default for Vector<T> {
    fn default() -> Vector<T> {
        Vector::new()
    }
}

impl<T> Index<usize> for Vector<T> {
    type Output = T;

    /// Element access, matching `immer::vector::operator[]`.
    ///
    /// # Panics
    ///
    /// Panics if `i >= size()`. (C++ leaves this undefined; Rust checks.)
    fn index(&self, i: usize) -> &T {
        match self.get(i) {
            Some(value) => value,
            None => panic!(
                "index out of bounds: the len is {} but the index is {}",
                self.size, i
            ),
        }
    }
}

impl<'a, T> IntoIterator for &'a Vector<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Iter<'a, T> {
        self.iter()
    }
}

impl<T: Clone> IntoIterator for Vector<T> {
    type Item = T;
    type IntoIter = IntoIter<T>;

    fn into_iter(self) -> IntoIter<T> {
        IntoIter::new(self)
    }
}

impl<T: Clone> FromIterator<T> for Vector<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Vector<T> {
        let mut vector = Vector::new();
        for item in iter {
            vector = vector.push_back(item);
        }
        vector
    }
}

impl<T: PartialEq> PartialEq for Vector<T> {
    fn eq(&self, other: &Vector<T>) -> bool {
