    /// The fully qualified C++ exception type this corresponds to.
    pub fn exception_type(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The exception's `what()` string, which for `std::stoi` is the function
    /// name.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

impl std::fmt::Display for StoiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.exception_type(), self.what())
    }
}

impl std::error::Error for StoiError {}

/// True for the characters C++'s `isspace` accepts in the default "C" locale.
fn is_cxx_space(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\u{b}' | '\u{c}' | '\r')
}

/// Parses a leading `int` out of `s` exactly as C++'s `std::stoi(s)` does.
///
/// # Examples
///
/// ```ignore
/// assert_eq!(stoi("42"), Ok(42));
/// assert_eq!(stoi("  -7xyz"), Ok(-7));
/// assert_eq!(stoi("0x10"), Ok(0));
/// assert_eq!(stoi("abc"), Err(StoiError::InvalidArgument));
/// assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
/// ```
pub fn stoi(s: &str) -> Result<i32, StoiError> {
    stoi_with_pos(s).map(|(value, _)| value)
}

/// Like [`stoi`], but also reports how many bytes were consumed — the value
/// `std::stoi` writes through its optional `pos` out-parameter.
pub fn stoi_with_pos(s: &str) -> Result<(i32, usize), StoiError> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_cxx_space(bytes[i] as char) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let digits_start = i;
    // Accumulate the magnitude. `strtol` keeps scanning digits after it has
    // overflowed (so the reported end position still covers them all) and then
    // reports a range error, so overflow is latched rather than returned early.
    let mut magnitude: u64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = u64::from(bytes[i] - b'0');
        if !overflowed {
            match magnitude.checked_mul(10).and_then(|m| m.checked_add(digit)) {
                Some(next) => magnitude = next,
                None => overflowed = true,
            }
        }
        i += 1;
    }

    if i == digits_start {
        // Not a single digit: `strtol` consumed nothing, so `stoi` throws.
        return Err(StoiError::InvalidArgument);
    }

    // `int` is two's-complement 32-bit, so the negative range extends one
    // further than the positive one.
    let limit: u64 = if negative {
        i32::MAX as u64 + 1
    } else {
        i32::MAX as u64
    };
    if overflowed || magnitude > limit {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative {
        (magnitude as i64).wrapping_neg() as i32
    } else {
        magnitude as i32
    };
    Ok((value, i))
}

