/// is observably identical down to the exit status.
pub fn terminate_with_uncaught_exception(error: StoiError) -> ! {
    eprint!(
        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
        error.exception_type(),
        error.what()
    );
    std::process::abort()
