//! C++ `int` arithmetic.
//!
//! The C++ original accumulates into `int` variables (`auto sum = 0;` deduces
//! `int`, and the elements are `int`). Rust's `+`/`*` panic on overflow in debug
//! builds and wrap in release builds, so neither operator on its own reproduces
//! the reference binary: GCC/Clang on x86-64 compile signed overflow to
//! two's-complement wrap-around, which is what the reference output shows.
//!
//! For example `n = 46341` prints `1073767311` and then `-2147432674`: the
//! doubled sum is `2147534622`, which wraps to `2147534622 - 2^32`. Using these
//! helpers keeps that behaviour explicit — and identical in debug and release.

/// Rust equivalent of C++'s `int` on every mainstream platform: 32-bit,
/// two's-complement.
pub type CInt = i32;

/// `a + b` with the wrap-around a C++ compiler emits for `int` overflow.
#[inline]
pub fn add(a: CInt, b: CInt) -> CInt {
    a.wrapping_add(b)
}

/// `a * b` with the wrap-around a C++ compiler emits for `int` overflow.
#[inline]
pub fn mul(a: CInt, b: CInt) -> CInt {
    a.wrapping_mul(b)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wraps_like_a_cxx_int() {
        assert_eq!(add(i32::MAX, 1), i32::MIN);
        assert_eq!(add(i32::MIN, -1), i32::MAX);
        assert_eq!(mul(1073767311, 2), -2147432674);
        assert_eq!(mul(i32::MIN, 2), 0);
    }

    #[test]
    fn matches_the_reference_binary_closed_form() {
        // sum(1..=n) accumulated in a wrapping `int`, then doubled per element.
        // Values checked against ./test11_executable for these n.
        for (n, first, second) in [
            (11i64, 66i32, 132i32),
            (65535, 2147450880, -65536),
            (65536, -2147450880, 65536),
            (46341, 1073767311, -2147432674),
            (92681, -37075, -74150),
            (1000000, 1784293664, -726379968),
        ] {
            let mut sum: CInt = 0;
            let mut doubled: CInt = 0;
            for i in 1..=n {
                sum = add(sum, i as CInt);
                doubled = add(doubled, mul(i as CInt, 2));
            }
            assert_eq!(sum, first, "first sum for n = {}", n);
            assert_eq!(doubled, second, "second sum for n = {}", n);
        }
    }
}

