//! Access to `argv`, matching the C++ program's view of it.

/// The process arguments, including `argv[0]`, so that indices line up with the
/// C++ `argv` and `args().len()` equals `argc`.
///
/// This is [`std::env::args`] with one deliberate difference: `std::env::args`
/// panics if any argument is not valid UTF-8, whereas C++ hands `main` raw bytes
/// and never fails. Going through [`std::env::args_os`] and replacing invalid
/// bytes keeps the C++ behaviour — such bytes are not digits, so the parse
/// outcome is the same one `std::stoi` would reach.
pub fn args() -> Vec<String> {
    std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect()
}

/// The `index`-th argument (`argv[index]`), or `None` when `argc <= index`.
pub fn arg(index: usize) -> Option<String> {
    args().into_iter().nth(index)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn argv_zero_is_always_present() {
        // The test harness is itself a process, so `argv[0]` exists.
        assert!(!args().is_empty());
        assert!(arg(0).is_some());
        assert_eq!(arg(usize::MAX), None);
    }
}

