input.new_string:
    #[test]
    fn structural_sharing_actually_shares() {
        // A push must not deep-copy the trie: the untouched left subtree of the
        // root has to be the very same allocation in both versions.
        let a: Vector<i32> = (0..2000).collect();
        let b = a.push_back(2000);
        let left_a = Rc::clone(&a.root().children()[0]);
        let left_b = Rc::clone(&b.root().children()[0]);
        assert!(Rc::ptr_eq(&left_a, &left_b));
    }

    #[test]
    fn the_trie_only_deepens_when_the_root_fills_up() {
        // A root at shift 5 addresses 32 leaves = 1024 trie elements, and the
        // tail holds 32 more, so element 1057 is the first that cannot fit.
        let mut v: Vector<usize> = Vector::new();
        for i in 0..1056 {
            v = v.push_back(i);
        }
        assert_eq!(v.shift, BITS, "still one level of inner nodes at n = 1056");
        assert_eq!(v.root.children().len(), BRANCHING);
        assert_eq!(v.tail.len(), BRANCHING);

        v = v.push_back(1056);
        assert_eq!(v.shift, 2 * BITS, "the root grew at n = 1057");
        assert_eq!(v.root.children().len(), 2);
        assert_eq!(v.tail.len(), 1);
        // ...and the elements survived the reshaping.
        assert_eq!(v.iter().copied().collect::<Vec<_>>(), (0..1057).collect::<Vec<_>>());
    }

    #[test]
    fn the_tail_holds_the_first_thirty_two_elements() {
        // Until a 33rd element arrives the trie stays empty: that is what makes
        // the first 32 pushes pure tail copies.
        let mut v: Vector<usize> = Vector::new();
        for i in 0..32 {
            v = v.push_back(i);
        }
        assert_eq!(v.tail_offset(), 0);
        assert_eq!(v.tail.len(), 32);
        assert!(v.root.children().is_empty());

        v = v.push_back(32);
        assert_eq!(v.tail_offset(), 32);
        assert_eq!(v.tail.len(), 1);
        assert_eq!(v.root.children().len(), 1);
    }
}

