#[test]
fn a_large_trie_agrees_with_a_plain_vec_element_by_element() {
    // The C++ program only prints sums, which are order-insensitive, so
    // element *placement* has to be checked directly: index order and
    // iteration order must both match a std Vec exactly.
    const N: usize = 40_000;
    let reference: Vec<usize> = (0..N).map(|i| i * 7 + 1).collect();
    let mut v: Vector<usize> = Vector::new();
    for value in &reference {
        v = v.push_back(*value);
    }
    assert_eq!(v.size(), N);
    for (i, expected) in reference.iter().enumerate() {
        assert_eq!(v[i], *expected, "index {}", i);
    }
    assert!(v.iter().eq(reference.iter()), "iteration order");
}

