    for n in [31808usize, 32800, 100_000, 1_048_576, 1_048_608, 2_000_000] {
        let mut v: Vector<u32> = Vector::new();
        for i in 0..n { v = v.push_back((i as u32).wrapping_mul(2654435761)); }
        assert_eq!(v.size(), n);
        for i in 0..n {
            assert_eq!(v[i], (i as u32).wrapping_mul(2654435761), "index {} of {}", i, n);
        }
        let mut k = 0usize;
        for (j, x) in v.iter().enumerate() {
            assert_eq!(*x, (j as u32).wrapping_mul(2654435761), "iter pos {} of {}", j, n);
            k += 1;
        }
        assert_eq!(k, n, "iteration length for n={}", n);
        // persistence across a depth increase: old version unaffected
        let w = v.push_back(7);
        assert_eq!(v.size(), n);
        assert_eq!(w.size(), n + 1);
        assert_eq!(w[n], 7);
        println!("n={:>9} OK (index + iteration order + persistence)", n);
    }
}
